#!/usr/bin/env node
// Generates THIRD_PARTY_NOTICES.md from front-end/package-lock.json (production dependencies only; development
// tooling is never shipped). Deterministic (sorted, no timestamps) so it can be checked in CI.
//   node generate-notices.mjs            write the file
//   node generate-notices.mjs --check    exit 1 if the committed file is out of date
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const lock = JSON.parse(readFileSync("front-end/package-lock.json", "utf8"));
const rows = Object.entries(lock.packages)
  .filter(([k, v]) => k && !v.dev)
  .map(([k, v]) => ({
    name: k.replace(/^.*node_modules\//, ""),
    version: v.version,
    license: typeof v.license === "string" ? v.license : v.license?.type || "UNKNOWN",
    optional: !!v.optional,
  }))
  .sort((a, b) => a.name.localeCompare(b.name) || a.version.localeCompare(b.version));

const md = `# Third-party notices

Selvara itself is proprietary (see [LICENSE](LICENSE)). It uses the open-source components below. Only **production
dependencies** are listed; development and build tooling is not part of what is delivered to users. This file is
generated by \`.github/scripts/generate-notices.mjs\` from \`front-end/package-lock.json\` and checked in CI, so it cannot
silently go stale. Licence texts ship inside each package in \`node_modules\` and are summarised in the SBOM attached
to every release.

## Attribution required by a licence

### caniuse-lite (CC-BY-4.0)

Browser-support data derived from the Can I Use database (caniuse.com, Alexis Deveria and contributors), packaged as
\`caniuse-lite\` and licensed under Creative Commons Attribution 4.0 International
(https://creativecommons.org/licenses/by/4.0/). It is used at build time to decide which browser prefixes and syntax to
emit. The data itself is **not** included in the deployed site. This project has not modified the data. The
authors do not endorse this product.

### libvips and sharp prebuilt binaries (LGPL-3.0-or-later)

The \`@img/sharp-*\` packages are optional prebuilt native binaries of the sharp image library and its libvips
dependency (LGPL-3.0-or-later). They are installed as optional dependencies of Next.js for image optimisation, which this
project does not use (no \`next/image\`). They are not modified, are dynamically linked native libraries, and are
**not part of the deployed output**: a CI check (\`.github/scripts/check-shipped-artifact.mjs\`) fails the build if any
sharp or libvips file or reference appears in what is shipped. Licence and source: https://github.com/lovell/sharp and
https://github.com/libvips/libvips.

## Production dependencies (${rows.length})

| Package | Version | Licence | Optional |
|---|---|---|---|
${rows.map((r) => `| ${r.name} | ${r.version} | ${r.license} | ${r.optional ? "yes" : ""} |`).join("\n")}
`;

if (process.argv.includes("--check")) {
  const have = existsSync("THIRD_PARTY_NOTICES.md") ? readFileSync("THIRD_PARTY_NOTICES.md", "utf8") : "";
  if (have !== md) { console.error("THIRD_PARTY_NOTICES.md is out of date. Run: node .github/scripts/generate-notices.mjs"); process.exit(1); }
  console.log(`THIRD_PARTY_NOTICES.md is up to date (${rows.length} production packages).`);
} else {
  writeFileSync("THIRD_PARTY_NOTICES.md", md);
  console.log(`Wrote THIRD_PARTY_NOTICES.md (${rows.length} production packages).`);
}
